def html_to_plain_text(html):
    result = ""
    in_tag = False

    for char in html:
        if char == '<':
            in_tag = True
        elif char == '>':
            in_tag = False
        elif not in_tag:
            if char in ['.', '!', '?']:
                result += char + "\n"  # New line after sentence terminator
            else:
                result += char

    return result.strip()

