class LinkedList:  
    def __init__(self):  
        self.head = None  

    def append(self, data):  
        new_node = Node(data)  
        if not self.head:  
            self.head = new_node  
            return  
        last = self.head  
        while last.next:  
            last = last.next  
        last.next = new_node  

    def display(self):  
        current = self.head  
        while current:  
            print(current.data, end=' -> ')  
            current = current.next  
        print('None')

class Maze:  
    def __init__(self, maze):  
        self.maze = maze  
        self.start = None  
        self.end = None  
        self.path = []  

    def set_start(self, x, y):  
        self.start = (x, y)  

    def set_end(self, x, y):  
        self.end = (x, y)  

    def is_wall(self, x, y):  
        return self.maze[y][x] == 1  

    def find_path(self):  
        if self.dfs(self.start[0], self.start[1]):  
            return self.path  
        return None  

    def dfs(self, x, y):  
        if (x, y) == self.end:  
            self.path.append((x, y))  
            return True  
        if self.is_wall(x, y):  
            return False  
        self.path.append((x, y))  
        # Recursive calls for movement  
        if (self.dfs(x + 1, y) or self.dfs(x - 1, y) or  
            self.dfs(x, y + 1) or self.dfs(x, y - 1)):  
            return True  
        self.path.pop()  
        return False

