class MemoryGame:
    def __init__(self):
        self.cards = ['A', 'B', 'C', 'D', 'E', 'F'] * 2
        random.shuffle(self.cards)
        self.found_pairs = []
        self.attempts = 0

    def display_cards(self):
        display = ['*' if card not in self.found_pairs else card for card in self.cards]
        print("Current Cards: ", ' '.join(display))

    def choose_cards(self):
        try:
            first = int(input("Choose the first card (0-11): "))
            second = int(input("Choose the second card (0-11): "))
            if first == second or first not in range(12) or second not in range(12):
                raise ValueError
            self.attempts += 1
            return first, second
        except ValueError:
            print("Invalid selection. Please choose different valid card indexes.")
            return self.choose_cards()

    def check_for_match(self, first, second):
        if self.cards[first] == self.cards[second]:
            print(f"Match found: {self.cards[first]} and {self.cards[second]}!")
            self.found_pairs.extend([self.cards[first]])
        else:
            print("No match. Try again!")

    def play_game(self):
        while len(self.found_pairs) < 6:
            self.display_cards()
            first, second = self.choose_cards()
            self.check_for_match(first, second)
            time.sleep(1)

        print(f"Congratulations! You've found all pairs in {self.attempts} attempts.")

