class MultiValueDict:  
    def __init__(self):  
        self.dict = {}  

    def add(self, key, value):  
        if key in self.dict:  
            self.dict[key].append(value)  
        else:  
            self.dict[key] = [value]  

    def get(self, key):  
        return self.dict.get(key, [])  

    def remove(self, key, value):  
        if key in self.dict:  
            try:  
                self.dict[key].remove(value)  
                if not self.dict[key]:  
                    del self.dict[key]  
            except ValueError:  
                pass  

    def __str__(self):  
        return str(self.dict)  

