def valid_permutations(s): 
    if len(s) == 1: 
        return [s] 
    perms = [] 
    for i, char in enumerate(s): 
        for perm in valid_permutations(s[:i] + s[i+1:]): 
            perms.append(char + perm) 
    return perms  # End of function definition.

