class HTMLExecutionEnvironment:
    def __init__(self):
        self.global_vars = {}
        self.stdout = []

    def add_global_variable(self, name, value):
        self.global_vars[name] = value

    def execute_code(self, code):
        exec_code = f"exec('''{code}''', self.global_vars)"
        self.capture_output(exec_code)

    def capture_output(self, code):
        import sys
        from io import StringIO
        old_stdout = sys.stdout
        sys.stdout = StringIO()

        try:
            exec_code
            output = sys.stdout.getvalue()
            self.stdout.append(output)
        finally:
            sys.stdout = old_stdout

    def analyze_code(self, code):
        imports = [line for line in code.splitlines() if line.startswith('import') or line.startswith('from')]
        variables = [var for var in self.global_vars if var in code]
        return {"imports": imports, "variables": variables}

