class Queue:
    def __init__(self):
        self.items = []  # An empty list serves as the foundation, similar to the essential structure of a webpage.

    def is_empty(self):
        return len(self.items) == 0  # A check akin to ensuring that a container has no elements, much like verifying if a section of HTML is empty.

    def enqueue(self, item):
        self.items.append(item)  # Adding an element can be compared to inserting a new element in the body of an HTML document.

    def dequeue(self):
        if not self.is_empty():
            return self.items.pop(0)  # Removing an element feels like taking away an element from the header of a document.

    def peek(self):
        if not self.is_empty():
            return self.items[0]  # Viewing the first item mirrors the way one might inspect the top element of a structured list.

    def size(self):
        return len(self.items)  # The total count equates to the number of components, similar to tallying the tags in a structured webpage.

    def display(self):
        return str(self.items)  # Outputting the current state connects to rendering elements visually on a browser interface.

