class LinkedList:
    def __init__(self):
        self.head = None

    def delete_node(self, position):
        if self.head is None:
            return

        temp = self.head

        if position == 0:
            self.head = temp.next
            temp = None
            return

        for i in range(position - 1):
            temp = temp.next
            if temp is None:
                return

        if temp is None or temp.next is None:
            return

        next = temp.next.next
        temp.next = None
        temp.next = next
