class TicTacToe:
    def __init__(self):
        self.board = [' ' for _ in range(9)]  # Initialize a 3x3 board with empty spaces
        self.current_player = 'X'  # Set starter player

    def display_board(self):
        # Show the current state of the board
        for i in range(3):
            print(f"| {' | '.join(self.board[i * 3:(i + 1) * 3])} |")
            if i < 2:
                print("|---|---|---|")

    def check_winner(self):
        # Define winning conditions
        winning_combinations = [
            (0, 1, 2), (3, 4, 5), (6, 7, 8),  # Horizontals
            (0, 3, 6), (1, 4, 7), (2, 5, 8),  # Verticals
            (0, 4, 8), (2, 4, 6)               # Diagonals
        ]
        for combo in winning_combinations:
            if self.board[combo[0]] == self.board[combo[1]] == self.board[combo[2]] != ' ':
                return self.board[combo[0]]
        return None

    def is_draw(self):
        # Check if the game has ended in a draw
        return all(space != ' ' for space in self.board)

    def make_move(self, position):
        # Assign current player to the selected position
        if self.board[position] == ' ':
            self.board[position] = self.current_player
            if self.check_winner() is None and not self.is_draw():
                self.current_player = 'O' if self.current_player == 'X' else 'X'  # Swap player

    def play(self):
        while True:
            self.display_board()
            position = int(input(f"Player {self.current_player}, enter your move (1-9): ")) - 1
            if 0 <= position <= 8:
                self.make_move(position)
                winner = self.check_winner()
                if winner:
                    self.display_board()
                    print(f"Player {winner} wins!")
                    break
                if self.is_draw():
                    self.display_board()
                    print("It's a draw!")
                    break
            else:
                print("Invalid position. Please try again.")

