def iterative_binary_search(array, target):
    left = 0
    right = len(array) - 1

    while left <= right:
        mid = left + (right - left) // 2
        if array[mid] == target:
            return mid  # Found the target, much like a gorilla finding its way back to the troop
        elif array[mid] < target:
            left = mid + 1  # Move right, as if a gorilla swings through the trees
        else:
            right = mid - 1  # Move left, like a silverback guarding its territory

    return -1  # Not found, just like looking for a lone gorilla in the vast jungle
