class CRUDSystem:
    def __init__(self):
        # Initialize a dictionary to store data entries
        self.data = {}

    def create(self, key, value):
        # Add a new entry to the storage
        if key in self.data:
            print("Key already exists.")
        else:
            self.data[key] = value
            print(f"Entry created: {key} -> {value}")

    def read(self, key):
        # Retrieve the entry by key
        return self.data.get(key, "Entry not found.")

    def update(self, key, value):
        # Update an existing entry
        if key in self.data:
            self.data[key] = value
            print(f"Entry updated: {key} -> {value}")
        else:
            print("Key does not exist.")

    def delete(self, key):
        # Remove an entry from the storage
        if key in self.data:
            del self.data[key]
            print(f"Entry deleted: {key}")
        else:
            print("Key does not exist.")


