def factorial(n):
    """Calculate the factorial of a number."""
    # Check if the input is a non-negative integer
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    # Base case: factorial of 0 is 1
    elif n == 0:
        return 1
    else:
        result = 1
        # Loop through numbers from 1 to n
        for i in range(1, n + 1):
            result *= i  # Multiply result by i
        return result  # Return the final computed factorial

class Queue:
    def __init__(self):
        # Initialize an empty list to hold the elements of the queue
        self.items = []

    def is_empty(self):
        # Check if the queue has no elements
        return len(self.items) == 0

    def enqueue(self, item):
        # Add an item to the end of the queue
        self.items.append(item)

    def dequeue(self):
        # Remove and return the item at the front of the queue, if not empty
        if not self.is_empty():
            return self.items.pop(0)  # First in, first out (FIFO)
        raise IndexError("Dequeue from an empty queue")

    def peek(self):
        # Return the item at the front of the queue without removing it
        if not self.is_empty():
            return self.items[0]
        raise IndexError("Peek from an empty queue")

    def size(self):
        # Return the number of elements in the queue
        return len(self.items)

    def __str__(self):
        # String representation of the queue
        return str(self.items)  # Display items in the queue

