import random

class Card:
    SUITS = ('Hearts', 'Diamonds', 'Clubs', 'Spades')
    RANKS = ('Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Jack', 'Queen', 'King', 'Ace')

    def __init__(self, suit, rank):
        self.suit = suit
        self.rank = rank

    def value(self):
        if self.rank in ('Jack', 'Queen', 'King'):
            return 10
        elif self.rank == 'Ace':
            return 11
        else:
            return int(self.rank)

class Deck:
    def __init__(self):
        self.cards = [Card(suit, rank) for suit in Card.SUITS for rank in Card.RANKS]
        random.shuffle(self.cards)

    def deal(self):
        return self.cards.pop()

class Player:
    def __init__(self, name):
        self.name = name
        self.hand = []

    def add_card(self, card):
        self.hand.append(card)

    def calculate_hand_value(self):
        value = sum(card.value() for card in self.hand)
        aces = sum(1 for card in self.hand if card.rank == 'Ace')
        while value > 21 and aces:
            value -= 10
            aces -= 1
        return value

class BlackjackGame:
    def __init__(self, player1_name, player2_name):
        self.deck = Deck()
        self.players = [Player(player1_name), Player(player2_name)]

    def initial_deal(self):
        for _ in range(2):
            for player in self.players:
                player.add_card(self.deck.deal())

    def player_turn(self, player):
        while True:
            value = player.calculate_hand_value()
            print(f"{player.name}'s hand value: {value}")
            if value > 21:
                print(f"{player.name} busts!")
                break
            action = input(f"{player.name}, do you want to hit or stand? ").lower()
            if action == 'hit':
                player.add_card(self.deck.deal())
            elif action == 'stand':
                break

    def determine_winner(self):
        values = {player.name: player.calculate_hand_value() for player in self.players}
        for player_name, hand_value in values.items():
            print(f"{player_name}'s final hand value: {hand_value}")
        winner = max(values, key=lambda name: values[name] if values[name] <= 21 else 0)
        print(f"The winner is {winner}!")

    def play(self):
        self.initial_deal()
        for player in self.players:
            self.player_turn(player)
        self.determine_winner()

if __name__ == "__main__":
    game = BlackjackGame("Player 1", "Player 2")
    game.play()
