class PathFinder:
    def __init__(self, maze):
        self.maze = maze
        self.visited = set()

    def find_path(self, position=None):
        if position is None:
            position = self.maze.start

        if position == self.maze.end:
            return True

        x, y = position
        if self.is_valid_move(x, y):
            self.visited.add(position)
            for next_step in self.get_possible_moves(x, y):
                if next_step not in self.visited and self.find_path(next_step):
                    return True
            self.visited.remove(position)

        return False

    def is_valid_move(self, x, y):
        return (0 <= x < len(self.maze.grid) and 
                0 <= y < len(self.maze.grid[0]) and
                self.maze.grid[x][y] == 1)  # assuming 1 is a walkable cell

    def get_possible_moves(self, x, y):
        return [(x+1, y), (x-1, y), (x, y+1), (x, y-1)]  # down, up, right, left

