class ColorStack:
    def __init__(self):
        self.stack = []

    def push(self, color_code):
        if self.is_valid_color(color_code):
            self.stack.append(color_code)
        else:
            raise ValueError("Invalid hexadecimal color code")

    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        else:
            raise IndexError("Pop from empty stack")

    def peek(self):
        if not self.is_empty():
            return self.stack[-1]
        else:
            raise IndexError("Peek from empty stack")

    def is_empty(self):
        return len(self.stack) == 0

    def size(self):
        return len(self.stack)

    def is_valid_color(self, color_code):
        return isinstance(color_code, str) and len(color_code) == 7 and color_code[0] == '#' and all(c in '0123456789abcdefABCDEF' for c in color_code[1:])

