        return tuple(int(hex_code[i:i+2], 16) for i in (0, 2, 4))

    def generate_json(self):
        color_attributes = {
            "color_name": self.color_name,
            "hex_code": self.hex_code,
            "rgb": self.rgb,
            "brightness": self.calculate_brightness(),
            "complementary": self.calculate_complementary()
        }
        return json.dumps(color_attributes)

    def calculate_brightness(self):
        r, g, b = self.rgb
        return (0.299 * r + 0.587 * g + 0.114 * b)

    def calculate_complementary(self):
        r, g, b = self.rgb
        comp_r = 255 - r
        comp_g = 255 - g
        comp_b = 255 - b
        return (comp_r, comp_g, comp_b)

