class LinearRegressionNN:
    def __init__(self, input_size, learning_rate=0.01):
        self.weights = [0.0] * input_size
        self.bias = 0.0
        self.learning_rate = learning_rate
        self.color_attributes = {
            'Red': '#FF0000',
            'Green': '#00FF00',
            'Blue': '#0000FF',
            'White': '#FFFFFF',
            'Black': '#000000',
        }

    def predict(self, x):
        return sum(w * x_i for w, x_i in zip(self.weights, x)) + self.bias

    def train(self, x_data, y_data, epochs):
        for _ in range(epochs):
            for x, y in zip(x_data, y_data):
                prediction = self.predict(x)
                error = prediction - y
                self.weights = [w - self.learning_rate * error * x_i for w, x_i in zip(self.weights, x)]
                self.bias -= self.learning_rate * error

    def display_colors(self):
