class MazeSolver:
    def __init__(self, maze):
        self.maze = maze
        self.start = (0, 0)
        self.end = (len(maze) - 1, len(maze[0]) - 1)
        self.path = []

    def is_valid(self, x, y):
        return 0 <= x < len(self.maze) and 0 <= y < len(self.maze[0]) and self.maze[x][y] == 0

    def solve(self, x=0, y=0):
        if (x, y) == self.end:
            self.path.append((x, y))
            return True
        if self.is_valid(x, y):
            self.path.append((x, y))
            self.maze[x][y] = '#'
            if (self.solve(x + 1, y) or self.solve(x, y + 1) or self.solve(x - 1, y) or self.solve(x, y - 1)):
                return True
            self.path.pop()
            self.maze[x][y] = 0
        return False

class ColorCode:
    def __init__(self, hex_code):
        self.hex_code = hex_code
        self.rgb = self.hex_to_rgb(hex_code)

