        return (
            int(hex_code[1:3], 16),
            int(hex_code[3:5], 16),
            int(hex_code[5:7], 16)
        )

    def luminance(self):
        r, g, b = self.rgb
        return 0.2126 * r + 0.7152 * g + 0.0722 * b

    def contrast(self, other):
        lum_self = self.luminance()
        lum_other = other.luminance()
        return abs(lum_self - lum_other)

