# Tic-tac-toe implementation

def initialize_board():
    return [[" " for _ in range(3)] for _ in range(3)]

def print_board(board):
    for row in board:
        print("|".join(row))
        print("-" * 5)

def check_winner(board, player):
    win_conditions = [
        [board[0][0], board[0][1], board[0][2]],  # Horizontal
        [board[1][0], board[1][1], board[1][2]],
        [board[2][0], board[2][1], board[2][2]],
        [board[0][0], board[1][0], board[2][0]],  # Vertical
        [board[0][1], board[1][1], board[2][1]],
        [board[0][2], board[1][2], board[2][2]],
        [board[0][0], board[1][1], board[2][2]],  # Diagonal
        [board[0][2], board[1][1], board[2][0]]
    ]
    return [player, player, player] in win_conditions

def is_draw(board):
    return all(cell != " " for row in board for cell in row)

def tic_tac_toe():
    board = initialize_board()
    current_player = "X"
    while True:
        print_board(board)
        try:
            row, col = map(int, input(f"Player {current_player}, enter your move (row, col): ").split())
            if board[row][col] == " ":
                board[row][col] = current_player
                if check_winner(board, current_player):
                    print_board(board)
                    print(f"Player {current_player} wins!")
                    break
                if is_draw(board):
                    print_board(board)
                    print("It's a draw!")
                    break
                current_player = "O" if current_player == "X" else "X"
            else:
                print("Cell already occupied, choose another.")
        except (ValueError, IndexError):
            print("Invalid input. Please enter row and column as two numbers from 0 to 2.")

