class Polynomial:
    def __init__(self, coefficients):
        self.coefficients = coefficients

    def degree(self):
        return len(self.coefficients) - 1

    def evaluate(self, x):
        result = 0
        for power, coeff in enumerate(self.coefficients):
            result += coeff * (x ** power)
        return result

    def __add__(self, other):
        max_len = max(len(self.coefficients), len(other.coefficients))
        new_coeffs = [0] * max_len
        for i in range(max_len):
            coeff_self = self.coefficients[i] if i < len(self.coefficients) else 0
            coeff_other = other.coefficients[i] if i < len(other.coefficients) else 0
            new_coeffs[i] = coeff_self + coeff_other
        return Polynomial(new_coeffs)

    def __str__(self):
        terms = []
        for power, coeff in enumerate(self.coefficients):
            if coeff != 0:
                term = f"{coeff}*x^{power}" if power > 0 else f"{coeff}"
                terms.append(term)
        return " + ".join(terms) if terms else "0"

class Fraction:
    def __init__(self, numerator, denominator):
        self.numerator = numerator
        self.denominator = denominator

    def __add__(self, other):
        new_numerator = (self.numerator * other.denominator) + (other.numerator * self.denominator)
        new_denominator = self.denominator * other.denominator
        return Fraction(new_numerator, new_denominator).simplify()

    def __sub__(self, other):
        new_numerator = (self.numerator * other.denominator) - (other.numerator * self.denominator)
        new_denominator = self.denominator * other.denominator
        return Fraction(new_numerator, new_denominator).simplify()

    def simplify(self):
        gcd = self._gcd(self.numerator, self.denominator)
        return Fraction(self.numerator // gcd, self.denominator // gcd)

    def _gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def __str__(self):
        return f"{self.numerator}/{self.denominator}"

