        self.suit = suit
        self.value = value

    def __str__(self):
        return f"{self.value} of {self.suit}"

class Deck:
    def __init__(self):
        self.cards = [Card(suit, value) for suit in ['Hearts', 'Diamonds', 'Clubs', 'Spades']
                      for value in ['2', '3', '4', '5', '6', '7', '8', '9', '10', 'Jack', 'Queen', 'King', 'Ace']]
        random.shuffle(self.cards)

    def deal_card(self):
        return self.cards.pop()

class Player:
    def __init__(self, name):
        self.name = name
        self.hand = []

    def add_card(self, card):
        self.hand.append(card)

    def calculate_score(self):
        score = 0
        aces = 0
        for card in self.hand:
            if card.value in ['Jack', 'Queen', 'King']:
                score += 10
            elif card.value == 'Ace':
                aces += 1
                score += 11
            else:
                score += int(card.value)

        while score > 21 and aces:
            score -= 10
            aces -= 1

        return score

def play_blackjack():
    deck = Deck()
    player1 = Player("Player 1")
    player2 = Player("Player 2")

    for _ in range(2):
        player1.add_card(deck.deal_card())
        player2.add_card(deck.deal_card())

    for player in [player1, player2]:
        while True:
            print(f"{player.name}'s hand: {[str(card) for card in player.hand]} - Score: {player.calculate_score()}")
            if player.calculate_score() >= 21:
                break
            action = input(f"{player.name}, would you like to 'hit' or 'stand'? ").strip().lower()
            if action == 'hit':
                player.add_card(deck.deal_card())
            elif action == 'stand':
                break

    score1 = player1.calculate_score()
    score2 = player2.calculate_score()

    print(f"{player1.name}'s final score: {score1}")
    print(f"{player2.name}'s final score: {score2}")

    if score1 > 21:
        print(f"{player1.name} busts! {player2.name} wins!")
    elif score2 > 21:
        print(f"{player2.name} busts! {player1.name} wins!")
    elif score1 > score2:
        print(f"{player1.name} wins!")
    elif score2 > score1:
        print(f"{player2.name} wins!")
    else:
        print("It's a tie!")

if __name__ == "__main__":
