    def __init__(self, string_value):
        self.string_value = string_value
        
    def convert(self):
        num = 0
        sign = 1
        index = 0
        
        if self.string_value and self.string_value[0] == '-':
            sign = -1
            index += 1
            
        while index < len(self.string_value):
            char = self.string_value[index]
            if char.isdigit():
                num = num * 10 + int(char)
            else:
                break
            index += 1
            
        return sign * num

