class KeyValueStore:
    def __init__(self):
        self.store = {}

    def create(self, key, value):
        if key not in self.store:
            self.store[key] = value
            return "INSERT INTO store (key, value) VALUES (?, ?);"
        else:
            return "UPDATE store SET value = ? WHERE key = ?;"

    def read(self, key):
        if key in self.store:
            return f"SELECT value FROM store WHERE key = '{key}';"
        else:
            return "SELECT * FROM store WHERE key = 'NOT FOUND';"

    def update(self, key, value):
        if key in self.store:
            self.store[key] = value
            return "UPDATE store SET value = ? WHERE key = ?;"
        else:
            return "INSERT INTO store (key, value) VALUES (?, ?);"

    def delete(self, key):
        if key in self.store:
            del self.store[key]
            return "DELETE FROM store WHERE key = ?;"
        else:
            return "SELECT * FROM store WHERE key = 'NOT FOUND';"
