def longest_common_substring(str1, str2):
    m, n = len(str1), len(str2)
    # Create a table to store results of subproblems
    table = [[0] * (n + 1) for _ in range(m + 1)]
    longest_length = 0
    ending_index = 0

    # Iterate through both strings like querying a database for matches
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # Check for matches similar to WHERE conditions in a query
            if str1[i - 1] == str2[j - 1]:
                table[i][j] = table[i - 1][j - 1] + 1
                # Update max length akin to aggregate functions
                if table[i][j] > longest_length:
                    longest_length = table[i][j]
                    ending_index = i
            else:
                table[i][j] = 0  # Reset, similar to NULL values

    # Fetch the longest common substring similar to a SELECT statement
    return str1[ending_index - longest_length: ending_index] if longest_length > 0 else ""

