class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def insert(self, data):
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    def delete(self, key):
        current = self.head
        previous = None

        while current and current.data != key:
            previous = current
            current = current.next

        if not current:
            return "Record not found"

        if not previous:
            self.head = current.next
        else:
            previous.next = current.next

        return f"Record with data '{key}' deleted"

    def display(self):
        current = self.head
        result = []
        while current:
            result.append(current.data)
            current = current.next
        return " -> ".join(map(str, result))

    def search(self, key):
        current = self.head
        while current:
            if current.data == key:
                return f"Record with data '{key}' exists"
            current = current.next
        return f"Record with data '{key}' not found"

