def tokenize_sentence(sentence):
    tokens = []
    buffer = ""

    for char in sentence:
        if char.isalnum() or char in ["'", "-"]:
            buffer += char
        else:
            if buffer:
                tokens.append(buffer)
                buffer = ""
            if not char.isspace():
                tokens.append(char)

    if buffer:
        tokens.append(buffer)

    return tokens

