class Stack:
    def __init__(self):
        self._elements = []

    def push(self, item):
        self._elements.append(item)

    def pop(self):
        if not self.is_empty():
            return self._elements.pop()
        return None

    def peek(self):
        if not self.is_empty():
            return self._elements[-1]
        return None

    def is_empty(self):
        return len(self._elements) == 0

    def size(self):
        return len(self._elements)

    def get_user_info(self):
        return {"size": self.size(), "top_item": self.peek() if not self.is_empty() else None}

