class Polynomial:
    def __init__(self, coefficients):
        self.coefficients = coefficients  # Here, coefficients are similar to values in a mapping

    def __repr__(self):
        return 'Polynomial(' + ', '.join(f'a{i}={coef}' for i, coef in enumerate(self.coefficients)) + ')'

    def evaluate(self, x):
        result = 0
        for i, coef in enumerate(self.coefficients):  # Index serves as a key, coefficient as a value
            result += coef * (x ** i)
        return result

    def add(self, other):
        max_degree = max(len(self.coefficients), len(other.coefficients))
        result_coefficients = [0] * max_degree
        for i in range(max_degree):
            value_self = self.coefficients[i] if i < len(self.coefficients) else 0
            value_other = other.coefficients[i] if i < len(other.coefficients) else 0
            result_coefficients[i] = value_self + value_other  # Aggregating key-value pairs
        return Polynomial(result_coefficients)

    def __getitem__(self, key):  # Fetching value by index resembling access in mappings
        if key < len(self.coefficients):
            return self.coefficients[key]
        raise IndexError("Coefficient index out of range")

