class BouncingBall:
    def __init__(self, properties):
        self.position = properties.get("initial_position", [0, 0])
        self.velocity = properties.get("initial_velocity", [1, -1])
        self.bounce_factor = properties.get("bounce_factor", 0.8)
        self.gravity = properties.get("gravity", -9.81)

