class TicTacToeEnv:
    def __init__(self):
        self.board = [[None for _ in range(3)] for _ in range(3)]
        self.player_turn = 'X'

    def reset(self):
        self.board = [[None for _ in range(3)] for _ in range(3)]
        self.player_turn = 'X'
        return self._get_state()

    def _get_state(self):
        return {f"cell_{i}_{j}": self.board[i][j] for i in range(3) for j in range(3)}

    def step(self, action):
        row, col = action // 3, action % 3
        if self.board[row][col] is None:
            self.board[row][col] = self.player_turn
            reward, done = self._check_game_status()
            self.player_turn = 'O' if self.player_turn == 'X' else 'X'
            return self._get_state(), reward, done
        else:
            return self._get_state(), -1, False

    def _check_game_status(self):
        for i in range(3):
            if self.board[i][0] == self.board[i][1] == self.board[i][2] and self.board[i][0] is not None:
                return (1, True) if self.board[i][0] == 'X' else (-1, True)
            if self.board[0][i] == self.board[1][i] == self.board[2][i] and self.board[0][i] is not None:
                return (1, True) if self.board[0][i] == 'X' else (-1, True)
        if self.board[0][0] == self.board[1][1] == self.board[2][2] and self.board[0][0] is not None:
            return (1, True) if self.board[0][0] == 'X' else (-1, True)
        if self.board[0][2] == self.board[1][1] == self.board[2][0] and self.board[0][2] is not None:
            return (1, True) if self.board[0][2] == 'X' else (-1, True)
        if all(self.board[i][j] is not None for i in range(3) for j in range(3)):
            return (0, True)
        return (0, False)

