class LongestCommonSubstringFinder:
    def __init__(self, string_a, string_b):
        self.string_a = string_a
        self.string_b = string_b

    def find_longest_common_substring(self):
        max_length = 0
        ending_index = 0
        dp_table = [[0] * (len(self.string_b) + 1) for _ in range(len(self.string_a) + 1)]

        for i in range(1, len(self.string_a) + 1):
            for j in range(1, len(self.string_b) + 1):
                if self.string_a[i - 1] == self.string_b[j - 1]:
                    dp_table[i][j] = dp_table[i - 1][j - 1] + 1
                    if dp_table[i][j] > max_length:
                        max_length = dp_table[i][j]
                        ending_index = i
                else:
                    dp_table[i][j] = 0

        return self.string_a[ending_index - max_length: ending_index]

