class Neural_Network:
    def __init__(self, input_size, hidden_size, output_size, learning_rate=0.01):
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size
        self.learning_rate = learning_rate
        self.weights_input_hidden = self.initialize_weights(input_size, hidden_size)
        self.weights_hidden_output = self.initialize_weights(hidden_size, output_size)

    def initialize_weights(self, in_size, out_size):
        return np.random.randn(in_size, out_size) * 0.01

    def forward(self, x):
        self.hidden_layer_activation = np.dot(x, self.weights_input_hidden)
        self.hidden_layer_output = self.activation_function(self.hidden_layer_activation)
        self.output_layer_activation = np.dot(self.hidden_layer_output, self.weights_hidden_output)
        return self.output_layer_activation

    def activation_function(self, x):
        return 1 / (1 + np.exp(-x))

    def compute_loss(self, y_true, y_pred):
        return np.mean((y_true - y_pred) ** 2)

    def backward(self, x, y_true, y_pred):
        error = y_pred - y_true
        d_output = error * self.activation_function_derivative(y_pred)
        error_hidden_layer = d_output.dot(self.weights_hidden_output.T)
        d_hidden_layer = error_hidden_layer * self.activation_function_derivative(self.hidden_layer_output)

        self.weights_input_hidden -= x.T.dot(d_hidden_layer) * self.learning_rate
        self.weights_hidden_output -= self.hidden_layer_output.T.dot(d_output) * self.learning_rate

    def activation_function_derivative(self, x):
        return x * (1 - x)

    def train(self, x, y, epochs):
        for _ in range(epochs):
            y_pred = self.forward(x)
            self.backward(x, y, y_pred)

# Instantiating the class
