class KMeans:
    def __init__(self, n_clusters=3, max_iterations=100):
        self.n_clusters = n_clusters
        self.max_iterations = max_iterations
        self.centroids = None

    def fit(self, data):
        self.centroids = data[:self.n_clusters].copy()
        for _ in range(self.max_iterations):
            labels = self._assign_labels(data)
            new_centroids = self._compute_centroids(data, labels)
            if (new_centroids == self.centroids).all():
                break
            self.centroids = new_centroids

    def _assign_labels(self, data):
        distances = self._calculate_distances(data)
        return distances.argmin(axis=1)

    def _calculate_distances(self, data):
        return np.linalg.norm(data[:, np.newaxis] - self.centroids, axis=2)

    def _compute_centroids(self, data, labels):
        return np.array([data[labels == i].mean(axis=0) for i in range(self.n_clusters)])

