        num_samples, num_features = X.shape
        unique_classes = set(y)

        if num_samples >= self.min_samples_split and depth < self.max_depth and len(unique_classes) > 1:
            best_split = self._best_split(X, y, num_features)
            if best_split:
                left_indices, right_indices = best_split['indices']
                left_node = self._grow_tree(X[left_indices], y[left_indices], depth + 1)
                right_node = self._grow_tree(X[right_indices], y[right_indices], depth + 1)
                return Node(feature=best_split['feature'], threshold=best_split['threshold'], left=left_node, right=right_node)

        return Node(value=self._most_common_label(y))

    def _best_split(self, X, y, num_features):
