from collections import Counter

def top_n_frequent(data, n=3):
    sorted_data = sorted(data, key=lambda x: x[0])
    grouped = groupby(sorted_data, key=lambda x: x[0])

    result = {}
    for key, group in grouped:
        count = Counter(item[1] for item in group)
        result[key] = count.most_common(n)

    return result

class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.value = key

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert_recursively(self.root, key)

    def _insert_recursively(self, current_node, key):
        if key < current_node.value:
            if current_node.left is None:
                current_node.left = Node(key)
            else:
                self._insert_recursively(current_node.left, key)
        else:
            if current_node.right is None:
                current_node.right = Node(key)
            else:
                self._insert_recursively(current_node.right, key)

    def search(self, key):
        return self._search_recursively(self.root, key)

    def _search_recursively(self, current_node, key):
        if current_node is None or current_node.value == key:
            return current_node
        if key < current_node.value:
            return self._search_recursively(current_node.left, key)
        return self._search_recursively(current_node.right, key)

    def inorder_traversal(self):
        return self._inorder_recursively(self.root)

    def _inorder_recursively(self, current_node):
        return (self._inorder_recursively(current_node.left) + 
                [current_node.value] + 
                self._inorder_recursively(current_node.right)) if current_node else []

