import numpy as np
from collections import Counter

class Node:
    def __init__(self, feature=None, threshold=None, left=None, right=None, output=None):
        self.feature = feature
        self.threshold = threshold
        self.left = left
        self.right = right
        self.output = output

class DecisionTree:
    def __init__(self, min_samples_split=2, max_depth=None):
        self.min_samples_split = min_samples_split
        self.max_depth = max_depth
        self.root = None

    def fit(self, X, y):
        self.root = self._grow_tree(X, y)

    def _grow_tree(self, X, y, depth=0):
        num_samples, num_features = X.shape
        unique_classes = np.unique(y)

        if len(unique_classes) == 1 or num_samples < self.min_samples_split:
            return Node(output=Counter(y).most_common(1)[0][0])

        if self.max_depth is not None and depth >= self.max_depth:
            return Node(output=Counter(y).most_common(1)[0][0])

        best_feature, best_threshold = self._best_split(X, y, num_features)
        left_indices = X[:, best_feature] < best_threshold
        right_indices = X[:, best_feature] >= best_threshold

        left_node = self._grow_tree(X[left_indices], y[left_indices], depth + 1)
        right_node = self._grow_tree(X[right_indices], y[right_indices], depth + 1)

        return Node(feature=best_feature, threshold=best_threshold, left=left_node, right=right_node)

    def _best_split(self, X, y, num_features):
        best_gain = -1
        split_idx, split_threshold = None, None

        for feature_idx in range(num_features):
            thresholds, classes = zip(*sorted(zip(X[:, feature_idx], y)))
            num_left = [0] * len(np.unique(y))
            num_total = Counter(y)

            for i in range(1, num_samples):
                c = classes[i - 1]
                num_left[c] += 1
                num_right = {k: num_total[k] - num_left[k] for k in num_total}

                left_impurity = self._gini(num_left, i)
                right_impurity = self._gini(num_right.values(), num_samples - i)
                gain = self._gini(num_total.values(), num_samples) - (i / num_samples) * left_impurity - ((num_samples - i) / num_samples) * right_impurity

                if thresholds[i] == thresholds[i - 1]:
                    continue

                if gain > best_gain:
                    best_gain = gain
                    split_idx = feature_idx
                    split_threshold = (thresholds[i] + thresholds[i - 1]) / 2

        return split_idx, split_threshold

    def _gini(self, counts, n):
        if n == 0:
            return 0
        return 1 - sum((count / n) ** 2 for count in counts)

    def predict(self, X):
        return [self._predict_sample(sample, self.root) for sample in X]

    def _predict_sample(self, sample, node):
        if node.output is not None:
            return node.output
        if sample[node.feature] < node.threshold:
            return self._predict_sample(sample, node.left)
        else:
            return self._predict_sample(sample, node.right)
