def calculate_amicable_sum(start, end):
    def get_divisor_sum(num):
        divisors = []
        for i in range(1, num):
            if num % i == 0:
                divisors.append(i)
        return sum(divisors)

    amicable_nums = set()
    for n in range(start, end + 1):
        potential_pair = get_divisor_sum(n)
        if potential_pair != n and get_divisor_sum(potential_pair) == n:
            amicable_nums.update([n, potential_pair])

    return sum(amicable_nums)

class Polynomial:
    def __init__(self, coefficients):
        # Store coefficients in reverse order for easier access
        self.coefficients = coefficients

    def degree(self):
        # Identify the highest degree of the polynomial
        return len(self.coefficients) - 1

    def evaluate(self, x):
        # Compute the polynomial's value at x
        return sum(coef * (x ** idx) for idx, coef in enumerate(self.coefficients))

    def add(self, other):
        # Add two polynomial objects
        max_length = max(len(self.coefficients), len(other.coefficients))
        new_coeffs = [0] * max_length

        for i in range(max_length):
            if i < len(self.coefficients):
                new_coeffs[i] += self.coefficients[i]
            if i < len(other.coefficients):
                new_coeffs[i] += other.coefficients[i]

        return Polynomial(new_coeffs)

    def multiply(self, other):
        # Multiply two polynomial objects
        new_length = len(self.coefficients) + len(other.coefficients) - 1
        new_coeffs = [0] * new_length

        for i in range(len(self.coefficients)):
            for j in range(len(other.coefficients)):
                new_coeffs[i + j] += self.coefficients[i] * other.coefficients[j]

        return Polynomial(new_coeffs)

    def __str__(self):
        # Create a string representation of the polynomial
        return ' + '.join(f'{coef}x^{i}' for i, coef in enumerate(self.coefficients) if coef != 0) or '0'

