    def __init__(self, x=0, y=0, z=0):
        self.configuration = {'x': x, 'y': y, 'z': z}
        self.rules = {
            'magnitude': self.calculate_magnitude(),
            'direction': self.calculate_direction()
        }

    def calculate_magnitude(self):
        x = self.configuration['x']
        y = self.configuration['y']
        z = self.configuration['z']
        return (x**2 + y**2 + z**2) ** 0.5

    def calculate_direction(self):
        magnitude = self.calculate_magnitude()
        if magnitude == 0:
            return {'x': 0, 'y': 0, 'z': 0}
        return {
            'x': self.configuration['x'] / magnitude,
            'y': self.configuration['y'] / magnitude,
            'z': self.configuration['z'] / magnitude
        }

    def add(self, other):
        return Vector3D(
            self.configuration['x'] + other.configuration['x'],
            self.configuration['y'] + other.configuration['y'],
            self.configuration['z'] + other.configuration['z']
        )

    def subtract(self, other):
        return Vector3D(
            self.configuration['x'] - other.configuration['x'],
            self.configuration['y'] - other.configuration['y'],
            self.configuration['z'] - other.configuration['z']
        )

    def __str__(self):
        return f"Vector3D({self.configuration['x']}, {self.configuration['y']}, {self.configuration['z']})"

