def prime_factors(n):
    # Initialize an empty list to store the factors
    factors = []

    # Configuration: Check for smallest primes, starting with 2
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Apply rules for odd factors starting from 3
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i

    # If n is a prime number greater than 2
