class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert_random_node(root, value):
    if root is None:
        return TreeNode(value)
    else:
        if random.choice([True, False]):
            root.left = insert_random_node(root.left, value)
        else:
            root.right = insert_random_node(root.right, value)
    return root

def create_random_binary_tree(depth, max_value):
    if depth == 0:
        return None
    value = random.randint(1, max_value)
    node = TreeNode(value)
    node.left = create_random_binary_tree(depth - 1, max_value)
    node.right = create_random_binary_tree(depth - 1, max_value)
    return node

def serialize_tree(root):
    if root is None:
        return None
    return {
        'value': root.value,
        'left': serialize_tree(root.left),
        'right': serialize_tree(root.right)
    }

