        while current:
            result.append(f"<item>{current.data}</item>")
            current = current.next
        return "<list>" + ''.join(result) + "</list>"

    def delete(self, key):
        current = self.head
        if current is not None:
            if current.data == key:
                self.head = current.next
                current = None
                return
        while current is not None:
            if current.data == key:
                break
            prev = current
            current = current.next
        if current is None:
            return
        prev.next = current.next
        current = None
