def extract_html_tags(text):
    import re
    return re.findall(r'<[^>]+>', text)

def count_html_tags(text):
    tags = extract_html_tags(text)
    return len(tags)

def extract_text_without_tags(text):
    clean_text = re.sub(r'<[^>]+>', '', text)
    return clean_text.strip()

def count_formatting_elements(text):
    formatting_tags = re.findall(r'</?(\b(?:b|i|u|strong|em|p|h[1-6])\b)[^>]*>', text)
    return len(formatting_tags)

def get_unique_tags(text):
    tags = extract_html_tags(text)
    return set(tags)

def highlight_formatting_elements(text):
    formatted_text = re.sub(r'(<b>|<strong>)(.*?)</\1>', r'<mark>\2</mark>', text)
    return formatted_text

def html_tag_frequency(text):
    tags = extract_html_tags(text)
    frequency = {}
    for tag in tags:
        frequency[tag] = frequency.get(tag, 0) + 1
    return frequency

