class Graph:
    def __init__(self):
        self.edges = {}  # Each node's connections

    def add_edge(self, from_node, to_node, weight=1):
        if from_node not in self.edges:
            self.edges[from_node] = []
        self.edges[from_node].append((to_node, weight))

    def shortest_path(self, start, end):
        visited = {}
        distance = {node: float('inf') for node in self.edges}
        distance[start] = 0
        for node in self.edges:
            visited[node] = False

        while True:
            current_node = None
            for node in self.edges:
                if not visited[node] and (current_node is None or distance[node] < distance[current_node]):
                    current_node = node

            if current_node is None or current_node == end:
                break

            visited[current_node] = True

            for neighbor, weight in self.edges.get(current_node, []):
                if visited[neighbor]:
                    continue
                new_distance = distance[current_node] + weight
                if new_distance < distance[neighbor]:
                    distance[neighbor] = new_distance

        return distance[end] if distance[end] != float('inf') else None

g = Graph()
g.add_edge('A', 'B', 1)
g.add_edge('A', 'C', 4)
g.add_edge('B', 'C', 2)
g.add_edge('B', 'D', 5)
g.add_edge('C', 'D', 1)

result = g.shortest_path('A', 'D')
print("Shortest path length from A to D:", result)
