import hashlib
import time

class Block:
    def __init__(self, index, timestamp, data, previous_hash):
        self.index = index
        self.timestamp = timestamp
        self.data = data
        self.previous_hash = previous_hash
        self.hash = self.calculate_hash()

    def calculate_hash(self):
        value = f"{self.index}{self.timestamp}{self.data}{self.previous_hash}"
        return hashlib.sha256(value.encode()).hexdigest()

class Blockchain:
    def __init__(self):
        self.chain = [self.create_genesis_block()]

    def create_genesis_block(self):
        return Block(0, time.time(), "Genesis Block", "0")

    def add_block(self, data):
        previous_block = self.chain[-1]
        new_index = previous_block.index + 1
        new_block = Block(new_index, time.time(), data, previous_block.hash)
        self.chain.append(new_block)

    def get_chain(self):
        return self.chain

# Usage example
blockchain = Blockchain()
blockchain.add_block({"name": "John Doe", "age": 30})
blockchain.add_block({"name": "Jane Smith", "age": 25})

for block in blockchain.get_chain():
    print(f"Block {block.index} Hash: {block.hash}, Data: {block.data}")
