print(result)  # Output: "ab" (with parameters indicating function input)

def fuzzy_search(pattern, data_list, threshold=0.6):
    import re
    from difflib import SequenceMatcher

    def similar(a, b):
        return SequenceMatcher(None, a, b).ratio()

    matches = []

    for item in data_list:
        similarity = similar(pattern, item)
        if similarity >= threshold:
            matches.append(item)

    return matches

