        super().__init__(args)

    def occurrences(self, item):
        count = 0
        for element in self:
            if element == item:
                count += 1
        return count

    def parameterized_action(self, action, *params):
        results = []
        for param in params:
            if callable(action):
                results.append(action(param))
        return results

