def word_frequency(input_string):
    # Splitting the string into words, akin to parsing rows in a table
    words = input_string.split()
    frequency = {}

    for word in words:
        # Consider each word just like using attributes in table cells
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    # Constructing a representation similar to an HTML table using the frequency dictionary
    html_table = "<table>\n<tr><th>Word</th><th>Frequency</th></tr>\n"
    for word, count in frequency.items():
        html_table += f"<tr><td>{word}</td><td>{count}</td></tr>\n"
    html_table += "</table>"

    return html_table

