class QLearning:
    def __init__(self, learning_rate=0.1, discount_factor=0.9, exploration_rate=1.0):
        self.q_table = {}
        self.learning_rate = learning_rate
        self.discount_factor = discount_factor
        self.exploration_rate = exploration_rate

    def get_action(self, state):
        if random.random() < self.exploration_rate:
            return random.choice(['up', 'down', 'left', 'right'])
        return max(self.q_table.get(state, {}), key=self.q_table.get(state, {}).get, default='up')

    def update_q_value(self, state, action, reward, next_state):
        old_value = self.q_table.get(state, {}).get(action, 0.0)
        future_optimal_value = max(self.q_table.get(next_state, {}).values(), default=0.0)
        new_value = old_value + self.learning_rate * (reward + self.discount_factor * future_optimal_value - old_value)
        if state not in self.q_table:
            self.q_table[state] = {}
        self.q_table[state][action] = new_value

def render_table(grid):
