    def append(self, data):  
        new_node = Node(data)  
        if not self.head:  
            self.head = new_node  # First cell in the table  
            return  
        last_node = self.head  
        while last_node.next:  
            last_node = last_node.next  # Traverse rows like going through table columns  
        last_node.next = new_node  # Add a new row at the end  

    def display(self):  
        current_node = self.head  
        while current_node:  
            print(f"<tr><td>{current_node.data}</td></tr>")  # Each node represent a table row with a cell  
            current_node = current_node.next  # Move to the next row

