class Node:
    def __init__(self, value):
        self.value = value  # String literal assigned to attribute
        self.left_child = None  # Variable identifier for left child
        self.right_child = None  # Variable identifier for right child

class BinaryTree:
    def __init__(self, root_value):
        self.root = Node(root_value)  # String literal used for root assignment

    def insert(self, value):
        self._insert_recursive(self.root, value)  # Using variable identifiers in a recursive call

    def _insert_recursive(self, current_node, value):
        if value < current_node.value:  # Comparison of variable identifiers
            if current_node.left_child is None:  # Check if left child is absent
                current_node.left_child = Node(value)  # String literal for new node
            else:
                self._insert_recursive(current_node.left_child, value)  # Recursive call for left child
        else:
            if current_node.right_child is None:  # Check if right child is absent
                current_node.right_child = Node(value)  # String literal for new node
            else:
                self._insert_recursive(current_node.right_child, value)  # Recursive call for right child

    def traverse_in_order(self):
        return self._traverse_in_order_recursive(self.root)  # Variable identifier used for traversal

    def _traverse_in_order_recursive(self, current_node):
        elements = []  # Variable identifier for storing traversal elements
        if current_node:
            elements.extend(self._traverse_in_order_recursive(current_node.left_child))  # Recursive call
            elements.append(current_node.value)  # Adding string literal from the current node
            elements.extend(self._traverse_in_order_recursive(current_node.right_child))  # Recursive call
        return elements  # Returning variable identifier with collected values

