import random

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert(root, value):
    if root is None:
        return Node(value)
    elif value < root.value:
        root.left = insert(root.left, value)
    else:
        root.right = insert(root.right, value)
    return root

def generate_random_tree(depth, max_value):
    if depth == 0:
        return None
    value = random.randint(1, max_value)
    root = Node(value)
    root.left = generate_random_tree(depth - 1, max_value)
    root.right = generate_random_tree(depth - 1, max_value)
    return root

