    votes[commit] += 1
    save_votes(votes)

def list_votes():
    votes = load_votes()
    for commit, count in votes.items():
        print(f"{commit}: {count} votes")

def tally_votes():
    votes = load_votes()
    return sum(votes.values())

def elect():
    votes = load_votes()
    if votes:
        elected_commit = max(votes, key=votes.get)
        print(f"Elected commit: {elected_commit} with {votes[elected_commit]} votes")
    else:
        print("No votes cast.")

