class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

def rotate_left(root):
    new_root = root.right
    root.right = new_root.left
    new_root.left = root
    return new_root

def rotate_right(root):
    new_root = root.left
    root.left = new_root.right
    new_root.right = root
    return new_root

def insert(node, key):
    if node is None:
        return TreeNode(key)
    elif key < node.val:
        node.left = insert(node.left, key)
    else:
        node.right = insert(node.right, key)
    return node

def inorder_traversal(root):
    return inorder_traversal(root.left) + [root.val] + inorder_traversal(root.right) if root else []

def build_balanced_bst(keys):
    keys.sort()
    return build_tree(keys)

def build_tree(keys):
    if not keys:
        return None
    mid = len(keys) // 2
    node = TreeNode(keys[mid])
    node.left = build_tree(keys[:mid])
    node.right = build_tree(keys[mid + 1:])
    return node

def optimize_bst(root):
    keys = inorder_traversal(root)
    return build_balanced_bst(keys)
