def value_of_card(card):
    rank, _ = card
    if rank in ['Jack', 'Queen', 'King']:
        return 10
    elif rank == 'Ace':
        return 11  # or 1 depending on context
    else:
        return int(rank)

def hand_value(hand):
    value = sum(value_of_card(card) for card in hand)
    aces = sum(1 for card in hand if card[0] == 'Ace')
    while value > 21 and aces:
        value -= 10
        aces -= 1
    return value

