def convert_number_to_words(num):
    if num < 0:
        return "minus " + convert_number_to_words(-num)
    elif num == 0:
        return "zero"

    units = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]
    thousands = ["", "thousand", "million", "billion"]

    def words(number):
        if number < 20:
            return units[number]
        elif number < 100:
            return tens[number // 10] + (" " + units[number % 10] if (number % 10) != 0 else "")
        elif number < 1000:
            return units[number // 100] + " hundred" + (" " + words(number % 100) if (number % 100) != 0 else "")
        else:
            for idx, word in enumerate(thousands):
                if number < 1000 ** (idx + 1):
                    return words(number // (1000 ** idx)) + " " + word + (" " + words(number % (1000 ** idx)) if (number % (1000 ** idx)) != 0 else "")

    return words(num).strip()

# Example usage
print(convert_number_to_words(1234567))  # one million two hundred thirty four thousand five hundred sixty seven

