class Polynomial:
    def __init__(self, coefficients):
        self.coefficients = coefficients  # list of coefficients, attribute akin to fields in a table

    def degree(self):
        # akin to retrieving metadata, this method computes the highest index with a non-zero value
        return len(self.coefficients) - 1 - self.coefficients[::-1].index(next(filter(lambda x: x != 0, self.coefficients[::-1]), None))

    def evaluate(self, x):
        # similar to executing a query that computes values based on attributes
        return sum(coef * (x ** idx) for idx, coef in enumerate(self.coefficients))

    def __add__(self, other):
        # combining data entries in a seamless merging, adaptable to varying lengths
        new_coefficients = [0] * max(len(self.coefficients), len(other.coefficients))
        for idx, coef in enumerate(self.coefficients):
            new_coefficients[idx] += coef
        for idx, coef in enumerate(other.coefficients):
            new_coefficients[idx] += coef
        return Polynomial(new_coefficients)

    def __str__(self):
        # formatting the polynomial in a user-friendly manner, resembling result presentation
        return " + ".join(f"{coef}x^{idx}" for idx, coef in enumerate(self.coefficients) if coef != 0)[::-1] or "0"

def binary_search(input_list, target):
    left_index = 0
    right_index = len(input_list) - 1

    while left_index <= right_index:
        mid_index = (left_index + right_index) // 2

        if input_list[mid_index] == target:
            return mid_index  # Found value in the dataset
        elif input_list[mid_index] < target:
            left_index = mid_index + 1  # Adjust range for higher attributes
        else:
            right_index = mid_index - 1  # Narrow down for lower attributes

    return -1  # Indicating that the target is absent from the structure

class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        # Here, the item represents an entry, similar to a row being added to a table
        self.items.append(item)

    def pop(self):
        # Removing an item could relate to deleting an entry, akin to removing a row
        if not self.is_empty():
            return self.items.pop()
        return None

    def is_empty(self):
        return len(self.items) == 0

    def peek(self):
        # The top item can be thought of as a view into the current state, similar to querying attributes
        if not self.is_empty():
            return self.items[-1]
        return None

