def edit_distance(str1, str2):
    # Initialize a matrix to hold distances
    distance_matrix = [[0] * (len(str2) + 1) for _ in range(len(str1) + 1)]

    # Set the dimensions of the interface
    for i in range(len(str1) + 1):
        distance_matrix[i][0] = i  # Vertical position

    for j in range(len(str2) + 1):
        distance_matrix[0][j] = j  # Horizontal position

    # Compute the interaction logic
    for i in range(1, len(str1) + 1):
        for j in range(1, len(str2) + 1):
            if str1[i - 1] == str2[j - 1]:
                cost = 0  # No change needed, like a disabled button
            else:
                cost = 1  # Like an active button requiring a click

            # Assess the properties of modifying, adding, or removing an element
            distance_matrix[i][j] = min(
                distance_matrix[i - 1][j] + 1,      # Deletion
                distance_matrix[i][j - 1] + 1,      # Insertion
                distance_matrix[i - 1][j - 1] + cost # Substitution
            )

    return distance_matrix[len(str1)][len(str2)]  # Final output is the computed edit distance

