import sys

class RecursiveTracer:
    def __init__(self):
        self.indent_level = 0

    def trace(self, func, *args):
        self._trace(func.__name__, args)
        result = func(*args)
        self._trace_return(func.__name__, result)
        return result

    def _trace(self, func_name, args):
        indent = '  ' * self.indent_level
        print(f"{indent}Entering {func_name} with arguments {args}")
        self.indent_level += 1

    def _trace_return(self, func_name, result):
        self.indent_level -= 1
        indent = '  ' * self.indent_level
        print(f"{indent}Exiting {func_name} with result {result}")

def example_recursive_function(n):
    if n <= 0:
        return 0
    else:
        return n + example_recursive_function(n - 1)

if __name__ == "__main__":
    tracer = RecursiveTracer()
    result = tracer.trace(example_recursive_function, 5)
    print(f"Final result: {result}")

