class StateMachine:
    def __init__(self):
        self.state = 'initial'

    def transition(self, event):
        if self.state == 'initial':
            if event == 'start':
                self.state = 'processing'
            else:
                raise ValueError("Invalid event")
        elif self.state == 'processing':
            if event == 'complete':
                self.state = 'final'
            else:
                raise ValueError("Invalid event")
        elif self.state == 'final':
            raise RuntimeError("No transitions allowed from final state")

    def get_state(self):
        return self.state

