def count_pairs_with_sum(arr, target_sum):
    # Initialize a hash map to store occurrences of each integer
    occurrences = {}
    pair_count = 0

    # Iterate through the array to count occurrences
    for number in arr:
        complement = target_sum - number
        if complement in occurrences:
            pair_count += occurrences[complement]

        # Update the hash map with the current number
        occurrences[number] = occurrences.get(number, 0) + 1

    return pair_count

