class ComplexNumber:
    def __init__(self, real, imaginary):
        self.real = real
        self.imaginary = imaginary

    def __add__(self, other):
        return ComplexNumber(self.real + other.real, self.imaginary + other.imaginary)

    def __sub__(self, other):
        return ComplexNumber(self.real - other.real, self.imaginary - other.imaginary)

    def __mul__(self, other):
        return ComplexNumber(self.real * other.real - self.imaginary * other.imaginary,
                             self.real * other.imaginary + self.imaginary * other.real)

    def __truediv__(self, other):
        denom = other.real**2 + other.imaginary**2
        return ComplexNumber((self.real * other.real + self.imaginary * other.imaginary) / denom,
                             (self.imaginary * other.real - self.real * other.imaginary) / denom)

    def __repr__(self):
        return f"{self.real} + {self.imaginary}i"

    @staticmethod
    def magnitude(complex_num):
        return (complex_num.real**2 + complex_num.imaginary**2) ** 0.5

    @staticmethod
    def phase(complex_num):
        import math
        return math.atan2(complex_num.imaginary, complex_num.real)

