class Block:
    def __init__(self, index, previous_hash, timestamp, data, hash):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.hash = hash

class Blockchain:
    def __init__(self):
        self.chain = []
        self.create_block(previous_hash='1', data='Genesis Block')

    def create_block(self, previous_hash, data):
        index = len(self.chain) + 1
        timestamp = self.get_current_time()
        hash = self.calculate_hash(index, previous_hash, timestamp, data)
        new_block = Block(index, previous_hash, timestamp, data, hash)
        self.chain.append(new_block)
        return new_block

    def get_current_time(self):
        from time import time
        return time()

    def calculate_hash(self, index, previous_hash, timestamp, data):
        import hashlib
        value = str(index) + previous_hash + str(timestamp) + str(data)
        return hashlib.sha256(value.encode()).hexdigest()

