class TowerOfHanoi:
    def __init__(self, num_disks):
        self.num_disks = num_disks
        self.source = 'A'
        self.target = 'B'
        self.auxiliary = 'C'

    def solve(self):
        self.move_disks(self.num_disks, self.source, self.target, self.auxiliary)

    def move_disks(self, n, source, target, auxiliary):
        if n == 1:
            print(f"Move disk 1 from {source} to {target}")
            return
        self.move_disks(n - 1, source, auxiliary, target)
        print(f"Move disk {n} from {source} to {target}")
        self.move_disks(n - 1, auxiliary, target, source)

