class PasswordStrengthChecker:
    def __init__(self, password):
        self.password = password

    def has_minimum_length(self, length=12):
        return len(self.password) >= length

    def has_uppercase(self):
        return any(char.isupper() for char in self.password)

    def has_lowercase(self):
        return any(char.islower() for char in self.password)

    def has_digit(self):
        return any(char.isdigit() for char in self.password)

    def has_special_character(self):
        special_characters = "!@#$%^&*()-_=+<>?"
        return any(char in special_characters for char in self.password)

    def check_strength(self):
        strength_checks = [
            self.has_minimum_length(),
            self.has_uppercase(),
            self.has_lowercase(),
            self.has_digit(),
            self.has_special_character(),
        ]
        if all(strength_checks):
            return "Strong password"
        elif sum(strength_checks) >= 3:
            return "Moderate password"
        else:
            return "Weak password"

