class ExponentialSeries:
    def __init__(self, base, terms):
        self.base = base
        self.terms = terms

    def calculate_series(self):
        result = 0
        factorial = 1
        for n in range(self.terms):
            if n > 0:
                factorial *= n
            result += (self.base ** n) / factorial
        return result

