class TreeNode:
    def __init__(self, value):
        self.value = value
        self.children = []

    def add_child(self, child_node):
        self.children.append(child_node)

def build_tree(value, depth):
    if depth == 0:
        return TreeNode(value)
    else:
        node = TreeNode(value)
        for i in range(2):  # Two children for each node
            child = build_tree(value + 1, depth - 1)
            node.add_child(child)
        return node

def print_tree(node, level=0):
    if node is not None:
        print(' ' * level * 2 + str(node.value))
        for child in node.children:
            print_tree(child, level + 1)

# Example call to build a tree of depth 3 starting from value 1
