def detect_spam(email_content):  
    def check_keywords(content):  
        spam_keywords = ["buy now", "free", "click here", "limited time", "money back"]  
        return any(keyword in content.lower() for keyword in spam_keywords)  

    def analyze_sender(sender):  
        known_spam_senders = ["spam@example.com", "offers@spam.com"]  
        return sender.lower() in known_spam_senders  

    def evaluate_email(email):  
        is_spam = False  
        if check_keywords(email.get("content", "")):  
            is_spam = True  
        if analyze_sender(email.get("sender", "")):  
            is_spam = True  
        return is_spam  

    return evaluate_email(email_content)

import numpy as np
from sklearn.cluster import KMeans

def generate_data(num_samples, num_features):
    return np.random.rand(num_samples, num_features)

def cluster_data(data, num_clusters):
