def longest_common_substring(str1, str2):
    m = len(str1)
    n = len(str2)
    longest = 0
    ending_index = 0
    length_matrix = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                length_matrix[i][j] = length_matrix[i - 1][j - 1] + 1
                if length_matrix[i][j] > longest:
                    longest = length_matrix[i][j]
                    ending_index = i
            else:
                length_matrix[i][j] = 0

    return str1[ending_index - longest: ending_index]

