def compute_word_frequency(input_string):
    # Split the string into words using whitespace
    words = input_string.split()
    # Create a dictionary to store frequency of each unique word
    frequency = {}

    # Loop through each word in the list
    for word in words:
        # Normalize words to lowercase for consistent counting
        normalized_word = word.lower()
        # Update the frequency count in the dictionary
        if normalized_word in frequency:
            frequency[normalized_word] += 1
        else:
            frequency[normalized_word] = 1

    # Return the dictionary containing word frequencies
    return frequency

class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BST:
    def __init__(self):
        self.root = None

    def insert(self, root, key):
        if root is None:
            return TreeNode(key)
        elif key < root.val:
            root.left = self.insert(root.left, key)
        else:
            root.right = self.insert(root.right, key)
        return root

    def inorder(self, root):
        return self.inorder(root.left) + [root.val] + self.inorder(root.right) if root else []

    def build_balanced_tree(self, nodes):
        if not nodes:
            return None
        mid = len(nodes) // 2
        root = TreeNode(nodes[mid])
        root.left = self.build_balanced_tree(nodes[:mid])
        root.right = self.build_balanced_tree(nodes[mid + 1:])
        return root

    def optimize(self):
        nodes = self.inorder(self.root)
        self.root = self.build_balanced_tree(nodes)

