from bs4 import BeautifulSoup
import requests

def make_mobile_friendly(url):
    response = requests.get(url)
    soup = BeautifulSoup(response.content, 'html.parser')

    # Add viewport meta tag
    viewport_tag = soup.new_tag('meta')
    viewport_tag.attrs['name'] = 'viewport'
    viewport_tag.attrs['content'] = 'width=device-width, initial-scale=1.0'
    soup.head.append(viewport_tag)

    # Optimize images for responsiveness
    for img in soup.find_all('img'):
        img['style'] = 'max-width: 100%; height: auto;'

    # Wrap content in a responsive container
    container_div = soup.new_tag('div', attrs={'class': 'container'})
    for child in soup.body.contents:
        container_div.append(child)
    soup.body.clear()
    soup.body.append(container_div)

    # Ensure CSS styles support mobile view
    style_tag = soup.new_tag('style')
    style_tag.string = '''
        body {
            font-size: 16px;
            line-height: 1.5;
        }
        .container {
            padding: 15px;
            margin: 0 auto;
            max-width: 100%;
        }
    '''
    soup.head.append(style_tag)

    return str(soup)

