def heuristic_algorithm(board, player):
    def is_winner(b, p):
        win_conditions = [(0, 1, 2), (3, 4, 5), (6, 7, 8),
                          (0, 3, 6), (1, 4, 7), (2, 5, 8),
                          (0, 4, 8), (2, 4, 6)]
        for condition in win_conditions:
            if all(b[i] == p for i in condition):
                return True
        return False

    def get_empty_positions(b):
        return [i for i, x in enumerate(b) if x == ' ']

    def evaluate_board(b):
        if is_winner(b, 'X'):
            return 1
        elif is_winner(b, 'O'):
            return -1
        return 0

    def minimax(b, depth, is_maximizing):
        score = evaluate_board(b)
        if score == 1 or score == -1:
            return score

        if not get_empty_positions(b):
            return 0

        if is_maximizing:
            best_score = float('-inf')
            for pos in get_empty_positions(b):
                b[pos] = 'X'
                best_score = max(best_score, minimax(b, depth + 1, False))
                b[pos] = ' '
            return best_score
        else:
            best_score = float('inf')
            for pos in get_empty_positions(b):
                b[pos] = 'O'
                best_score = min(best_score, minimax(b, depth + 1, True))
                b[pos] = ' '
            return best_score

    best_move = -1
    best_value = float('-inf')
    for pos in get_empty_positions(board):
        board[pos] = 'X'
        move_value = minimax(board, 0, False)
        board[pos] = ' '
        if move_value > best_value:
            best_value = move_value
            best_move = pos
    return best_move

